function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawWorld(){
ctx.fillStyle='#25302d';ctx.fillRect(0,0,WORLD.w,WORLD.h);
// city blocks and asphalt grid
for(let x=0;x<WORLD.w;x+=WORLD.step){for(let y=0;y<WORLD.h;y+=WORLD.step){ctx.fillStyle='#303837';ctx.fillRect(x,y,WORLD.step,WORLD.step)}}
ctx.fillStyle='#343b3c';for(let x=180;x<WORLD.w;x+=360)ctx.fillRect(x-63,0,126,WORLD.h);for(let y=180;y<WORLD.h;y+=360)ctx.fillRect(0,y-63,WORLD.w,126);
// sidewalks and street-edge curbs
ctx.fillStyle='#62605a';for(let x=180;x<WORLD.w;x+=360){ctx.fillRect(x-70,0,7,WORLD.h);ctx.fillRect(x+63,0,7,WORLD.h)}for(let y=180;y<WORLD.h;y+=360){ctx.fillRect(0,y-70,WORLD.w,7);ctx.fillRect(0,y+63,WORLD.w,7)}
// lane markings
ctx.strokeStyle='#c2b58b';ctx.lineWidth=2;ctx.setLineDash([17,18]);for(let x=180;x<WORLD.w;x+=360){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,WORLD.h);ctx.stroke()}for(let y=180;y<WORLD.h;y+=360){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WORLD.w,y);ctx.stroke()}ctx.setLineDash([]);
// crosswalks, manholes, street lamps
for(let x=180;x<WORLD.w;x+=360)for(let y=180;y<WORLD.h;y+=360){ctx.fillStyle='#b8b2a1';for(let k=-3;k<=3;k++){ctx.fillRect(x-59+k*16,y-57,8,2);ctx.fillRect(x-59+k*16,y+55,8,2);ctx.fillRect(x-57,y-59+k*16,2,8);ctx.fillRect(x+55,y-59+k*16,2,8)}ctx.fillStyle='#252c2d';ctx.beginPath();ctx.ellipse(x+34,y+33,7,5,0,0,7);ctx.fill()}
// backdrop lot texture
for(let y=0;y<WORLD.h;y+=24)for(let x=0;x<WORLD.w;x+=24){if((Math.floor(x/24)*7+Math.floor(y/24)*11)%13===0){ctx.fillStyle='#38413a';ctx.fillRect(x+4,y+4,2,2)}}
// buildings, shadows and roof dressing
const tones=[['#6b6256','#554e45'],['#59615d','#424b48'],['#746752','#594d40'],['#535c65','#404850']];
for(const b of buildings){if(b.x+b.w<player.x-W/2-100||b.x>player.x+W/2+100||b.y+b.h<player.y-H/2-100||b.y>player.y+H/2+100)continue;const [base,dark]=tones[b.tone];ctx.fillStyle='#10171888';ctx.fillRect(b.x+12,b.y+15,b.w,b.h);ctx.fillStyle='#7d796e';ctx.fillRect(b.x-6,b.y-6,b.w+12,b.h+12);ctx.fillStyle=base;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle=dark;ctx.fillRect(b.x,b.y,b.w,8);ctx.fillRect(b.x,b.y,8,b.h);
// roof panels / air vents
ctx.fillStyle='#ffffff0b';ctx.fillRect(b.x+18,b.y+18,b.w-36,4);ctx.fillStyle='#343b3b';ctx.fillRect(b.x+b.w*.58,b.y+b.h*.18,36,25);ctx.fillStyle='#7a796f';ctx.fillRect(b.x+b.w*.58+4,b.y+b.h*.18+4,28,4);ctx.fillStyle='#454b48';ctx.fillRect(b.x+b.w*.18,b.y+b.h*.63,55,18);ctx.fillStyle='#727267';for(let i=0;i<4;i++)ctx.fillRect(b.x+b.w*.18+5+i*12,b.y+b.h*.63+4,5,10);
// windows / facade edge
ctx.fillStyle='#b6a87955';for(let x=b.x+20;x<b.x+b.w-8;x+=25){ctx.fillRect(x,b.y+b.h-7,13,3);ctx.fillRect(x,b.y+6,10,3)}
}
// district signs
ctx.font='900 11px system-ui';ctx.letterSpacing='3px';for(const d of districts){ctx.fillStyle='#ddd0ac66';ctx.fillText(d.t,d.x,d.y)}ctx.letterSpacing='0px';
// objective and safehouse markers
const target=hasPackage?safe:drop,pulse=.5+.5*Math.sin(gameTime*4);ctx.strokeStyle=hasPackage?'#a9d57b':'#e9b55e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(target.x,target.y,24+pulse*8,0,Math.PI*2);ctx.stroke();ctx.fillStyle=hasPackage?'#b8e889':'#f2c271';ctx.beginPath();ctx.arc(target.x,target.y,5,0,Math.PI*2);ctx.fill();ctx.font='900 9px system-ui';ctx.fillStyle='#fff';ctx.textAlign='center';ctx.fillText(hasPackage?'SAFEHOUSE':'THE DROP',target.x,target.y-36);ctx.textAlign='left';
}
function drawCar(c,police=false){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.a);if(police){let flash=Math.sin(c.flash)>0;ctx.fillStyle='#090d0fee';ctx.fillRect(-21,-13,46,27);ctx.fillStyle='#bbc3c2';ctx.fillRect(-19,-11,38,22);ctx.fillStyle='#1f3038';ctx.fillRect(-6,-10,13,20);ctx.fillStyle=flash?'#f05c54':'#467cc4';ctx.fillRect(-4,-14,9,4);ctx.fillStyle='#eee';ctx.fillRect(15,-9,4,5);ctx.fillRect(15,5,4,5);ctx.fillStyle='#b93131';ctx.fillRect(-20,-9,3,5);ctx.fillRect(-20,5,3,5)}else{ctx.fillStyle='#090d0fcc';ctx.fillRect(-22,-13,46,27);ctx.fillStyle=c.color;ctx.fillRect(-20,-11,40,22);ctx.fillStyle='#1e2b30';ctx.fillRect(-7,-9,13,18);ctx.fillStyle='#657479';ctx.fillRect(9,-8,8,16);ctx.fillStyle='#e2d9bd';ctx.fillRect(16,-9,4,5);ctx.fillRect(16,4,4,5);ctx.fillStyle='#822e2e';ctx.fillRect(-20,-9,3,5);ctx.fillRect(-20,4,3,5)}ctx.restore()}

